-- GENERATED by tests/bench/world2/make_head_impl.py from commit 046d1e2.  The fill and broadcast functions before the work of docs/PERF-WORLD2.md, schema bench_head.
create schema if not exists bench_head;

create or replace function bench_head.fill_section(p_dim text, p_cx int, p_sy int, p_cz int, a_x int, b_x int, a_y int, b_y int, a_z int, b_z int, p_nm text, p_default_biome text)
returns int language plpgsql volatile set plan_cache_mode = force_generic_plan as $$
declare
    v_bc int; v_fc int; v_pal text[]; v_bits int; v_data bytea; sec_ok boolean;
    v_bpal text[]; v_bbits int; v_bdata bytea;
    nbox     int := (b_x - a_x + 1) * (b_y - a_y + 1) * (b_z - a_z + 1);
    whole    boolean := (b_x - a_x + 1) * (b_y - a_y + 1) * (b_z - a_z + 1) = 4096;
    nm_air  boolean := mc.is_air(p_nm);
    nm_fl   boolean := mc.has_fluid(p_nm);
    n_old   int;                              -- palette entries before the new block was appended
    newpos  int;                              -- palette position (1-based) of the new block
    nv      bigint;                           -- its entry value
    nb      int;
    counting boolean := true;                 -- false when the old content is known (a single-value section): then nothing is counted
    b       int;  vpl int;  nw int;  msk bigint;
    words   bigint[]; ow bigint[];
    ou      bigint[]; fm bigint[];            -- ou[j + 1]: bit 0 of the first j fields; fm[j + 1]: all bits of the first j fields
    shs     int[] := '{}';                    -- the shift schedule of the zero-field test
    cov     int;  sh int;
    ones    bigint;                           -- bit 0 of every field
    trep    bigint[] := '{}';                 -- per tracked value: that value in every field.  [1] the new block, then the old air entries, then the old fluid entries
    tc      bigint[] := '{}';                 -- ... and how many fields inside the box equal it
    n_air   int := 0;  n_fl int := 0;  nt int := 0;
    y int; z int; i0 int; i1 int; w int; ws int; lo int; hi int; mo bigint; mk bigint; old bigint; yv bigint; f bigint; t int; k int; s int; e int;
    changed int; old_air bigint := 0; old_fl bigint := 0;
    bm      bytea;
    xx int; idx int;
    rep     bigint;
begin
    select s.block_count, s.fluid_count, s.palette, s.bits, s.data, s.biome_palette, s.biome_bits, s.biome_data
      into v_bc, v_fc, v_pal, v_bits, v_data, v_bpal, v_bbits, v_bdata
      from mc.chunk_section s where s.dimension = p_dim and s.cx = p_cx and s.cz = p_cz and s.sy = p_sy for update;
    sec_ok := found;
    if not sec_ok then
        v_bc := 0; v_fc := 0; v_pal := array['minecraft:air']; v_bits := 0; v_data := ''::bytea; v_bpal := array[p_default_biome]; v_bbits := 0; v_bdata := ''::bytea;
    end if;
    if cardinality(v_pal) = 0 or (v_bits = 0 and cardinality(v_pal) <> 1) then return -1; end if;      -- global palette (or an unexpected single-value layout): the general path
    n_old := cardinality(v_pal);
    newpos := array_position(v_pal, p_nm);

    if v_bits = 0 then
        if newpos is not null then return 0; end if;                       -- the section already is that block everywhere
        changed := nbox;
        old_air := case when mc.is_air(v_pal[1]) then nbox else 0 end;      -- everything inside the box is the old single value
        old_fl  := case when mc.has_fluid(v_pal[1]) then nbox else 0 end;
        if whole then
            v_bc := case when nm_air then 0 else 4096 end; v_fc := case when nm_fl then 4096 else 0 end;
            v_pal := array[p_nm]; v_data := ''::bytea;                      -- a single-value section again (v_bits stays 0)
            bm := mc.block_event_full_cells();
        else
            v_pal := v_pal || p_nm; newpos := 2; v_bits := 4; v_data := null;
            counting := false;
            bm := mc.box_bitmap(a_x, b_x, a_y, b_y, a_z, b_z);
        end if;
    else
        if newpos is null then
            v_pal := v_pal || p_nm; newpos := cardinality(v_pal); nb := mc.block_bits_for(newpos);
            if nb = 16 then return -1; end if;                              -- the palette outgrows 8 bits: the global palette, the general path
            if nb > v_bits then v_data := mc.pack_longs(mc.unpack_longs(v_data, v_bits, 4096), nb); v_bits := nb; end if;
        end if;
    end if;
    nv := newpos - 1;

    if not (v_bits = 0 and whole) then
        ---------------------------------------------------------------- set the box fields word by word; count (SWAR) unless the old content is known
        b := v_bits; vpl := 64 / b; nw := (4096 + vpl - 1) / vpl; msk := (1::bigint << b) - 1;
        ou := array_fill(0::bigint, array[vpl + 1]); fm := array_fill(0::bigint, array[vpl + 1]);
        rep := 0;
        for k in 0 .. vpl - 1 loop
            ou[k + 2] := ou[k + 1] | (1::bigint << (k * b));
            fm[k + 2] := fm[k + 1] | (msk << (k * b));
            rep := rep | (nv << (k * b));
        end loop;
        ones := ou[vpl + 1];
        if counting then
            cov := 1;
            while cov < b loop sh := least(cov, b - cov); shs := shs || sh; cov := cov + sh; end loop;
            -- the values to count: the new block (it tells how many positions change) and, unless the whole section is replaced (the new counts are then known), the entries
            -- of the old palette that are air or hold a fluid (the block and fluid counts)
            trep := array[rep]; tc := array[0::bigint]; nt := 1;
            if not whole then
                for e in 0 .. n_old - 1 loop
                    if mc.is_air(v_pal[e + 1]) then
                        rep := 0; for k in 0 .. vpl - 1 loop rep := rep | (e::bigint << (k * b)); end loop;
                        trep := trep || rep; tc := tc || 0::bigint; nt := nt + 1; n_air := n_air + 1;
                    end if;
                end loop;
                for e in 0 .. n_old - 1 loop
                    if mc.has_fluid(v_pal[e + 1]) then
                        rep := 0; for k in 0 .. vpl - 1 loop rep := rep | (e::bigint << (k * b)); end loop;
                        trep := trep || rep; tc := tc || 0::bigint; nt := nt + 1; n_fl := n_fl + 1;
                    end if;
                end loop;
            end if;
            words := array(select proto.i64_read(v_data, w2 * 8) from generate_series(0, nw - 1) w2 order by w2);
            ow := words;
        else
            words := array_fill(0::bigint, array[nw]);
        end if;
        rep := trep[1];
        if not counting then
            rep := 0; for k in 0 .. vpl - 1 loop rep := rep | (nv << (k * b)); end loop;
        end if;

        for y in a_y .. b_y loop
            for z in a_z .. b_z loop
                i0 := (y << 8) | (z << 4) | a_x;
                i1 := i0 + (b_x - a_x);
                w := i0 / vpl;
                loop
                    ws := w * vpl;
                    lo := greatest(i0, ws) - ws;
                    hi := least(i1, ws + vpl - 1) - ws;
                    mo := ou[hi + 2] & ~ou[lo + 1];                        -- bit 0 of the fields inside the box
                    mk := fm[hi + 2] & ~fm[lo + 1];                        -- all bits of them
                    old := words[w + 1];
                    if counting then
                        for t in 1 .. nt loop
                            yv := old # trep[t];                           -- zero field = equal to the counted value
                            f := yv;
                            foreach sh in array shs loop f := f | (f >> sh); end loop;
                            tc[t] := tc[t] + bit_count(int8send(((f & ones) # ones) & mo));
                        end loop;
                    end if;
                    words[w + 1] := (old & ~mk) | (rep & mk);
                    exit when ws + vpl > i1;
                    w := w + 1;
                end loop;
            end loop;
        end loop;

        if counting then
            changed := nbox - tc[1]::int;
            for t in 2 .. 1 + n_air loop old_air := old_air + tc[t]; end loop;
            for t in 2 + n_air .. 1 + n_air + n_fl loop old_fl := old_fl + tc[t]; end loop;
            if changed = 0 then return 0; end if;                           -- nothing differs: nothing is written, no event
            if tc[1] = 0 then
                bm := case when whole then mc.block_event_full_cells() else mc.box_bitmap(a_x, b_x, a_y, b_y, a_z, b_z) end;
            else
                -- only some positions of the box differed: read them off the old words
                bm := decode(repeat('00', 512), 'hex');
                for y in a_y .. b_y loop
                    for z in a_z .. b_z loop
                        for xx in a_x .. b_x loop
                            idx := (y << 8) | (z << 4) | xx;
                            if ((ow[idx / vpl + 1] >> ((idx % vpl) * b)) & msk) <> nv then
                                bm := set_byte(bm, idx >> 3, get_byte(bm, idx >> 3) | (1 << (idx & 7)));
                            end if;
                        end loop;
                    end loop;
                end loop;
            end if;
            if whole then
                v_bc := case when nm_air then 0 else 4096 end; v_fc := case when nm_fl then 4096 else 0 end;
                v_pal := array[p_nm]; v_bits := 0; v_data := ''::bytea;
            else
                v_bc := v_bc - (nbox - old_air::int) + (case when nm_air then 0 else nbox end);
                v_fc := v_fc - old_fl::int + (case when nm_fl then nbox else 0 end);
            end if;
        else
            -- (a single-value section that became a palette section: the counts follow from the old value)
            v_bc := v_bc - (nbox - old_air::int) + (case when nm_air then 0 else nbox end);
            v_fc := v_fc - old_fl::int + (case when nm_fl then nbox else 0 end);
        end if;
        if v_bits > 0 then
            v_data := (select string_agg(int8send(x), ''::bytea order by o) from unnest(words) with ordinality t2(x, o));
        end if;
    end if;

    if sec_ok then
        update mc.chunk_section s set block_count = v_bc, fluid_count = v_fc, palette = v_pal, bits = v_bits, data = v_data
         where s.dimension = p_dim and s.cx = p_cx and s.cz = p_cz and s.sy = p_sy;
    else
        insert into mc.chunk_section (dimension, cx, cz, sy, block_count, fluid_count, palette, bits, data, biome_palette, biome_bits, biome_data)
        values (p_dim, p_cx, p_cz, p_sy, v_bc, v_fc, v_pal, v_bits, v_data, v_bpal, v_bbits, v_bdata)
        on conflict (dimension, cx, cz, sy) do update
           set block_count = excluded.block_count, fluid_count = excluded.fluid_count, palette = excluded.palette, bits = excluded.bits, data = excluded.data;
    end if;
    insert into mc.block_event (kind, dimension, x, y, z, old_state, new_state, cells) values ('cells', p_dim, p_cx * 16, p_sy * 16, p_cz * 16, '*', p_nm, bm);
    return changed;
end $$;

create or replace function bench_head.fill(p_dim text, x1 int, y1 int, z1 int, x2 int, y2 int, z2 int, p_block text) returns int language plpgsql volatile as $$
declare
    d       mc.dimension%rowtype;
    nm      text := mc.canon_state(p_block);
    lo_x    int := least(x1, x2);  hi_x int := greatest(x1, x2);
    lo_y    int := least(y1, y2);  hi_y int := greatest(y1, y2);
    lo_z    int := least(z1, z2);  hi_z int := greatest(z1, z2);
    v_cx    int; v_cz int; v_sy int;
    a_x     int; b_x int; a_y int; b_y int; a_z int; b_z int;
    idxs    int[];
    covered int := 0;
    n_box   int;
    r       int;
    secs    int;                                   -- sections of the current chunk written by mc.fill_section
begin
    select * into d from mc.dimension where name = p_dim;
    if not found then raise exception 'unknown dimension %', p_dim; end if;
    if lo_y < d.min_y or hi_y >= d.min_y + d.height then raise exception 'fill is outside dimension % (y % .. %)', p_dim, d.min_y, d.min_y + d.height - 1; end if;
    insert into mc.chunk (dimension, cx, cz)
    select p_dim, cx, cz from generate_series(lo_x >> 4, hi_x >> 4) cx, generate_series(lo_z >> 4, hi_z >> 4) cz on conflict do nothing;
    for v_cx in (lo_x >> 4) .. (hi_x >> 4) loop
      for v_cz in (lo_z >> 4) .. (hi_z >> 4) loop
        secs := 0;
        for v_sy in (lo_y >> 4) .. (hi_y >> 4) loop
            a_x := greatest(lo_x, v_cx * 16); b_x := least(hi_x, v_cx * 16 + 15);
            a_y := greatest(lo_y, v_sy * 16); b_y := least(hi_y, v_sy * 16 + 15);
            a_z := greatest(lo_z, v_cz * 16); b_z := least(hi_z, v_cz * 16 + 15);
            n_box := (b_x - a_x + 1) * (b_y - a_y + 1) * (b_z - a_z + 1);
            covered := covered + n_box;
            r := -1;
            if n_box > 48 then
                r := bench_head.fill_section(p_dim, v_cx, v_sy, v_cz, a_x & 15, b_x & 15, a_y & 15, b_y & 15, a_z & 15, b_z & 15, nm, d.default_biome);
                if r > 0 then secs := secs + 1; end if;
            end if;
            if r = -1 then
                idxs := array(select mc.section_idx(x, y, z) from generate_series(a_x, b_x) x, generate_series(a_y, b_y) y, generate_series(a_z, b_z) z order by z, y, x);      -- /fill's order: x fastest, then y, then z
                perform mc.edit_section(p_dim, v_cx, v_sy, v_cz, idxs, array_fill(nm, array[cardinality(idxs)]), true);
            end if;
        end loop;
        if secs > 0 then
            update mc.chunk c set version = c.version + secs, dirty = true, hm_dirty = true where c.dimension = p_dim and c.cx = v_cx and c.cz = v_cz;
        end if;
      end loop;
    end loop;
    return covered;
end $$;

create or replace function bench_head.broadcast_block_events() returns int language plpgsql as $$
declare r int := mc.prop_int('view-distance') + 1; i_bu int := mc.pid('block_update'); i_le int := mc.pid('level_event'); i_ack int := mc.pid('block_changed_ack'); n int := 0;
        e_id bigint[]; e_kind text[]; e_dim text[]; e_x int[]; e_y int[]; e_z int[]; e_old text[]; e_new text[]; e_cells bytea[];      -- every event of the tick
        a_dim text[]; a_x int[]; a_y int[]; a_z int[]; a_old int[]; a_new int[];          -- the net changes of the per-block events: dimension, position, old and new state id
        u_dim text[]; u_x int[]; u_y int[]; u_z int[]; u_id int[];                          -- sections with one changed position: that position and its state
        kd text[]; kx int[]; kz int[];                                        -- the chunks whose sections were replaced whole
        s record; ord int[]; ids int[]; full_ord int[]; full_ins int[]; ins int[]; full_cells bytea; k int;
        m_cx int[] := '{}'; m_cz int[] := '{}'; m_pkt bytea[] := '{}'; mn int := 0;     -- the packets of multi-position sections: chunk, bytes
begin
    -- (idle early return: no recorded block change, section change or pending acknowledgement)
    if not exists (select 1 from mc.block_event) and not exists (select 1 from mc.pending_ack) then return 0; end if;
    -- The per-tick sets live in arrays, not in temp tables (sql/437), and the queue is consumed with DELETE ... RETURNING instead of TRUNCATE.
    with ev as (delete from mc.block_event returning id, kind, dimension, x, y, z, old_state, new_state, cells)
    select array_agg(id), array_agg(kind), array_agg(dimension), array_agg(x), array_agg(y), array_agg(z), array_agg(old_state), array_agg(new_state), array_agg(cells)
      into e_id, e_kind, e_dim, e_x, e_y, e_z, e_old, e_new, e_cells from ev;

    if e_id is not null then
        -- net change per position of the per-block events (the break effect): the first old state against the last new one
        with g as (select dimension, x, y, z, (array_agg(old_state order by id))[1] as old_state, (array_agg(new_state order by id desc))[1] as new_state
                     from unnest(e_id, e_kind, e_dim, e_x, e_y, e_z, e_old, e_new) u(id, kind, dimension, x, y, z, old_state, new_state)
                    where kind = 'block' group by dimension, x, y, z
                   having (array_agg(old_state order by id))[1] <> (array_agg(new_state order by id desc))[1])
        select array_agg(dimension), array_agg(x), array_agg(y), array_agg(z), array_agg(mc.block_state_id(old_state)), array_agg(mc.block_state_id(new_state))
          into a_dim, a_x, a_y, a_z, a_old, a_new from g;

        -- sections of per-block events with exactly one changed position: block_update with the state the position has now
        with ev as (select * from unnest(e_id, e_kind, e_dim, e_x, e_y, e_z, e_new, e_cells) u(id, kind, dimension, x, y, z, new_state, cells) where kind <> 'section'),
             sec as (select dimension, x >> 4 as cx, y >> 4 as sy, z >> 4 as cz from ev group by 1, 2, 3, 4
                     having not bool_or(kind = 'cells') and count(distinct (x, y, z)) = 1),
             one as (select distinct on (ev.dimension, ev.x, ev.y, ev.z) ev.dimension, ev.x, ev.y, ev.z, ev.new_state
                       from ev join sec on sec.dimension = ev.dimension and sec.cx = ev.x >> 4 and sec.sy = ev.y >> 4 and sec.cz = ev.z >> 4
                      order by ev.dimension, ev.x, ev.y, ev.z, ev.id desc)
        select array_agg(dimension order by x, y, z), array_agg(x order by x, y, z), array_agg(y order by x, y, z), array_agg(z order by x, y, z),
               array_agg(mc.block_state_id(new_state) order by x, y, z)
          into u_dim, u_x, u_y, u_z, u_id from one;
        n := coalesce(cardinality(u_x), 0);

        -- (the chunks in the order their first change was recorded)
        select array_agg(t.dimension order by t.first_id), array_agg(t.cx order by t.first_id), array_agg(t.cz order by t.first_id) into kd, kx, kz
          from (select dimension, x >> 4 as cx, z >> 4 as cz, min(id) as first_id from unnest(e_id, e_kind, e_dim, e_x, e_z) u(id, kind, dimension, x, z) where kind = 'section'
                 group by dimension, x >> 4, z >> 4) t;

        -- sections with two or more changed positions, or a fill: the events of each, in order.  A fill's cells are expanded only for the sections some connection can see.
        select c.ord, c.ins into full_ord, full_ins from mc.sbu_const c where c.id = 1;
        full_cells := mc.block_event_full_cells();
        for s in
            with ev as (select * from unnest(e_id, e_kind, e_dim, e_x, e_y, e_z, e_new, e_cells) u(id, kind, dimension, x, y, z, new_state, cells) where kind <> 'section')
            select dimension, x >> 4 as cx, y >> 4 as sy, z >> 4 as cz, count(*) as nev, bool_or(kind = 'cells') as has_cells,
                   array_agg(kind order by id) as kinds,
                   array_agg(((x & 15) << 8) | ((z & 15) << 4) | (y & 15) order by id) as bpos,        -- (only meaningful for per-block events)
                   array_agg(cells order by id) as cellss, array_agg(new_state order by id) as news
              from ev group by dimension, x >> 4, y >> 4, z >> 4
             having bool_or(kind = 'cells') or count(distinct (x, y, z)) >= 2
             order by dimension, cx, cz, sy
        loop
            -- only sections some connection can see are encoded
            if not exists (select 1 from net.conn c where c.state = 'play' and not c.closing and c.view_cx is not null and abs(c.view_cx - s.cx) <= r and abs(c.view_cz - s.cz) <= r) then
                continue;
            end if;
            if s.nev = 1 and s.has_cells and s.cellss[1] = full_cells then ord := full_ord;           -- one fill of the whole section: the order is a constant
            else
                if not s.has_cells then ins := s.bpos;
                else
                    ins := '{}';
                    for k in 1 .. s.nev loop
                        if s.kinds[k] = 'block' then ins := ins || s.bpos[k];
                        elsif s.cellss[k] = full_cells then ins := ins || full_ins;
                        else ins := ins || bench_head.cells_positions(s.cellss[k]); end if;
                    end loop;
                end if;
                ord := bench_head.shortset_order(ins);
            end if;
            if s.nev = 1 and s.has_cells then ids := array_fill(mc.block_state_id(s.news[1]), array[cardinality(ord)]);     -- the only change of the section this tick: every position holds that block
            else ids := bench_head.section_state_ids(s.dimension, s.cx, s.sy, s.cz, ord); end if;
            mn := mn + 1;
            m_cx[mn] := s.cx; m_cz[mn] := s.cz; m_pkt[mn] := bench_head.section_update_packet(s.cx, s.sy, s.cz, ord, ids);
            n := n + cardinality(ord);
        end loop;

        if cardinality(a_x) > 0 then
            -- the break effect for everybody except the player who did it
            insert into mc.play_out (conn_id, data)
            select c.conn_id, proto.frame(i_le, proto.i32(2001) || proto.position(b.x, b.y, b.z) || proto.i32(b.old_id) || '\x00'::bytea)
            from unnest(a_dim, a_x, a_y, a_z, a_old, a_new) as b(dimension, x, y, z, old_id, new_id)
            join net.conn c on c.state = 'play' and not c.closing and c.view_cx is not null and abs(c.view_cx - (b.x >> 4)) <= r and abs(c.view_cz - (b.z >> 4)) <= r
            where b.new_id = 0 and b.old_id <> 0
              and not exists (select 1 from mc.block_actor a where a.dimension = b.dimension and a.x = b.x and a.y = b.y and a.z = b.z and a.conn_id = c.conn_id)
            order by b.x, b.y, b.z;
        end if;
        if cardinality(u_x) > 0 then
            insert into mc.play_out (conn_id, data)
            select c.conn_id, proto.frame(i_bu, proto.position(b.x, b.y, b.z) || proto.varint(b.new_id))
            from unnest(u_dim, u_x, u_y, u_z, u_id) as b(dimension, x, y, z, new_id)
            join net.conn c on c.state = 'play' and not c.closing and c.view_cx is not null and abs(c.view_cx - (b.x >> 4)) <= r and abs(c.view_cz - (b.z >> 4)) <= r
            order by b.x, b.y, b.z;
        end if;
        if mn > 0 then
            insert into mc.play_out (conn_id, data)
            select c.conn_id, k.pkt
            from unnest(m_cx, m_cz, m_pkt) with ordinality as k(cx, cz, pkt, ord)
            join net.conn c on c.state = 'play' and not c.closing and c.view_cx is not null and abs(c.view_cx - k.cx) <= r and abs(c.view_cz - k.cz) <= r
            order by k.ord, c.conn_id;
        end if;
        if kx is not null then
            insert into mc.play_out (conn_id, data)
            select c.conn_id, mc.chunk_packet(k.dimension, k.cx, k.cz)
            from unnest(kd, kx, kz) with ordinality as k(dimension, cx, cz, ord) join net.conn c on c.state = 'play' and not c.closing and c.view_cx is not null and abs(c.view_cx - k.cx) <= r and abs(c.view_cz - k.cz) <= r
            order by k.ord, c.conn_id;
        end if;
    end if;

    -- the acknowledgement: only the latest sequence of each connection this tick, after its block updates
    with a as (delete from mc.pending_ack returning conn_id, sequence)
    insert into mc.play_out (conn_id, data) select conn_id, proto.frame(i_ack, proto.varint(max(sequence))) from a group by conn_id;
    delete from mc.block_actor;
    return n;
end $$;

create or replace function bench_head.shortset_order(p_pos int[]) returns int[] language plpgsql immutable parallel safe as $$
declare
    n        int := 32;
    mask     int := 31;
    maxfill  int := 24;
    size     int := 0;
    tab      int[] := array_fill(0, array[32]);       -- slot s (0-based) holds position + 1, 0 = empty
    has_null boolean := false;
    k int; h bigint; p int; v int; dup boolean;
    nn int; nm int; nt int[]; i int;
    res      int[]; c int := 0;
begin
    foreach k in array p_pos loop
        if k = 0 then
            continue when has_null;
            has_null := true;
        else
            h := (k::bigint * 2654435769) & 4294967295;              -- HashCommon.mix: h = k * 0x9E3779B9 (32 bit), h ^ (h >>> 16)
            p := ((h # (h >> 16)) & mask)::int;
            dup := false;
            loop
                v := tab[p + 1];
                exit when v = 0;
                if v = k + 1 then dup := true; exit; end if;
                p := (p + 1) & mask;
            end loop;
            continue when dup;
            tab[p + 1] := k + 1;
        end if;
        size := size + 1;
        if size - 1 >= maxfill then                                       -- add(): if (size++ >= maxFill) rehash(arraySize(size + 1, f))
            nn := n * 2; nm := nn - 1; nt := array_fill(0, array[nn]);
            for i in reverse n .. 1 loop
                v := tab[i];
                continue when v = 0;
                h := ((v - 1)::bigint * 2654435769) & 4294967295;
                p := ((h # (h >> 16)) & nm)::int;
                while nt[p + 1] <> 0 loop p := (p + 1) & nm; end loop;
                nt[p + 1] := v;
            end loop;
            tab := nt; n := nn; mask := nm; maxfill := nn * 3 / 4;
        end if;
    end loop;
    res := array_fill(0, array[size]);
    if has_null then c := 1; res[1] := 0; end if;
    for i in reverse n .. 1 loop
        if tab[i] <> 0 then c := c + 1; res[c] := tab[i] - 1; end if;
    end loop;
    return res;
end $$;

create or replace function bench_head.cells_positions(c bytea) returns int[] language sql immutable parallel safe as $$
  select coalesce(array_agg((x << 8) | (z << 4) | y order by z, y, x), '{}')
    from generate_series(0, 15) z, generate_series(0, 15) y, generate_series(0, 15) x
   where get_bit(c, (y << 8) | (z << 4) | x) = 1 $$;

create or replace function bench_head.section_state_ids(p_dim text, p_cx int, p_sy int, p_cz int, p_pos int[]) returns int[] language plpgsql stable as $$
declare
    pal   text[]; bits int; data bytea; ids int[]; res int[] := '{}'; n int := cardinality(p_pos);
    vpl   int; msk bigint; words bigint[]; i int; e int; k int;
begin
    select s.palette, s.bits, s.data into pal, bits, data from mc.chunk_section s where s.dimension = p_dim and s.cx = p_cx and s.cz = p_cz and s.sy = p_sy;
    if not found then return array_fill(0, array[n]); end if;
    if bits = 0 then return array_fill((select s.state_id from ref.block_state s where s.name = pal[1]), array[n]); end if;
    if cardinality(pal) > 0 then ids := mc.palette_ids(pal); end if;
    vpl := 64 / bits; msk := (1::bigint << bits) - 1;
    res := array_fill(0, array[n]);
    if n >= 64 then
        words := array(select proto.i64_read(data, w * 8) from generate_series(0, (4096 + vpl - 1) / vpl - 1) w order by w);
    end if;
    for k in 1 .. n loop
        i := ((p_pos[k] >> 8) & 15) | (p_pos[k] & 240) | ((p_pos[k] & 15) << 8);              -- vanilla index -> storage index (y << 8 | z << 4 | x)
        if n >= 64 then e := ((words[i / vpl + 1] >> ((i % vpl) * bits)) & msk)::int;
        else e := ((proto.i64_read(data, (i / vpl) * 8) >> ((i % vpl) * bits)) & msk)::int; end if;
        res[k] := case when ids is null then e else ids[e + 1] end;
    end loop;
    return res;
end $$;

create or replace function bench_head.varint_u28(v int) returns bytea language sql immutable parallel safe as $$
  select substring(int8send(((((v & 127) | (case when v >= 128 then 128 else 0 end)))::bigint << 24)
                          | ((((v >> 7) & 127) | (case when v >= 16384 then 128 else 0 end))::bigint << 16)
                          | ((((v >> 14) & 127) | (case when v >= 2097152 then 128 else 0 end))::bigint << 8)
                          | ((v >> 21) & 127)::bigint)
                   from 5 for (case when v < 128 then 1 when v < 16384 then 2 when v < 2097152 then 3 else 4 end)) $$;

create or replace function bench_head.section_update_packet(p_cx int, p_sy int, p_cz int, p_ord int[], p_ids int[]) returns bytea language plpgsql stable as $$
declare n int := cardinality(p_ord);
begin
    if n = 1 then
        return proto.frame(mc.pid('block_update'), proto.position(p_cx * 16 + (p_ord[1] >> 8), p_sy * 16 + (p_ord[1] & 15), p_cz * 16 + ((p_ord[1] >> 4) & 15)) || proto.varint(p_ids[1]));
    end if;
    return proto.frame(mc.pid('section_blocks_update'),
        int8send(((p_cx::bigint & 4194303) << 42) | (p_sy::bigint & 1048575) | ((p_cz::bigint & 4194303) << 20)) || proto.varint(n)
        || (select string_agg(bench_head.varint_u28((u.id << 12) | u.pos), ''::bytea order by u.o) from unnest(p_ord, p_ids) with ordinality u(pos, id, o)));
end $$;

